-- ============================================================================
-- Shared-schema multi-tenancy with one workspace per user.
--
-- This migration:
--   1. Creates the `tenants` table and `TenantStatus` enum.
--   2. Adds a nullable `tenantId` to every tenant-owned table.
--   3. Creates a single default tenant and assigns ALL existing rows to it.
--   4. Makes `tenantId` required and adds foreign keys + indexes.
--
-- The fixed default-tenant UUID is used only for the backfill. New tenants
-- created by the application will use UUIDs generated by Prisma.
-- ============================================================================

-- CreateEnum
CREATE TYPE "TenantStatus" AS ENUM ('TRIAL', 'ACTIVE', 'SUSPENDED', 'CANCELLED');

-- CreateTable
CREATE TABLE "tenants" (
    "id" UUID NOT NULL,
    "name" VARCHAR(255) NOT NULL,
    "slug" VARCHAR(100) NOT NULL,
    "status" "TenantStatus" NOT NULL DEFAULT 'TRIAL',
    "plan" VARCHAR(50) NOT NULL DEFAULT 'free',
    "trialEndsAt" TIMESTAMPTZ(6),
    "settings" JSONB,
    "createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(6) NOT NULL,
    "deletedAt" TIMESTAMPTZ(6),

    CONSTRAINT "tenants_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "tenants_slug_key" ON "tenants"("slug");

-- AlterTable: add tenantId as nullable first so the backfill can run safely
ALTER TABLE "users" ADD COLUMN "tenantId" UUID;
ALTER TABLE "incomeCategories" ADD COLUMN "tenantId" UUID;
ALTER TABLE "expenseCategories" ADD COLUMN "tenantId" UUID;
ALTER TABLE "incomes" ADD COLUMN "tenantId" UUID;
ALTER TABLE "expenses" ADD COLUMN "tenantId" UUID;
ALTER TABLE "notes" ADD COLUMN "tenantId" UUID;
ALTER TABLE "remainders" ADD COLUMN "tenantId" UUID;
ALTER TABLE "auditlogs" ADD COLUMN "tenantId" UUID;
ALTER TABLE "attachments" ADD COLUMN "tenantId" UUID;

-- Create the default workspace that will own all pre-existing data.
-- `settings` starts with the app's current defaults (NPR, Kathmandu).
INSERT INTO "tenants" (
    "id",
    "name",
    "slug",
    "status",
    "plan",
    "settings",
    "createdAt",
    "updatedAt"
) VALUES (
    '00000000-0000-0000-0000-000000000001',
    'Default Workspace',
    'default',
    'ACTIVE',
    'free',
    '{"currency":"NPR","timezone":"Asia/Kathmandu"}'::JSONB,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
)
ON CONFLICT ("id") DO NOTHING;

-- Backfill every existing row into the default workspace.
UPDATE "users" SET "tenantId" = '00000000-0000-0000-0000-000000000001' WHERE "tenantId" IS NULL;
UPDATE "incomeCategories" SET "tenantId" = '00000000-0000-0000-0000-000000000001' WHERE "tenantId" IS NULL;
UPDATE "expenseCategories" SET "tenantId" = '00000000-0000-0000-0000-000000000001' WHERE "tenantId" IS NULL;
UPDATE "incomes" SET "tenantId" = '00000000-0000-0000-0000-000000000001' WHERE "tenantId" IS NULL;
UPDATE "expenses" SET "tenantId" = '00000000-0000-0000-0000-000000000001' WHERE "tenantId" IS NULL;
UPDATE "notes" SET "tenantId" = '00000000-0000-0000-0000-000000000001' WHERE "tenantId" IS NULL;
UPDATE "remainders" SET "tenantId" = '00000000-0000-0000-0000-000000000001' WHERE "tenantId" IS NULL;
UPDATE "auditlogs" SET "tenantId" = '00000000-0000-0000-0000-000000000001' WHERE "tenantId" IS NULL;
UPDATE "attachments" SET "tenantId" = '00000000-0000-0000-0000-000000000001' WHERE "tenantId" IS NULL;

-- Fail with a clear message before adding unique constraints if the existing
-- data cannot satisfy them. Resolve duplicates, then re-run the migration.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM "users"
        GROUP BY "userEmail"
        HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'Cannot add unique constraint users.userEmail: duplicate email addresses exist. Resolve duplicates before migrating.';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM "incomeCategories"
        GROUP BY "categoryName"
        HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'Cannot add unique constraint incomeCategories(tenantId, categoryName): duplicate income category names exist. Resolve duplicates before migrating.';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM "expenseCategories"
        GROUP BY "categoryName"
        HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'Cannot add unique constraint expenseCategories(tenantId, categoryName): duplicate expense category names exist. Resolve duplicates before migrating.';
    END IF;
END $$;

-- Make tenantId required. Audit logs stay nullable so platform/system events
-- that are not tied to a workspace can still be recorded.
ALTER TABLE "users" ALTER COLUMN "tenantId" SET NOT NULL;
ALTER TABLE "incomeCategories" ALTER COLUMN "tenantId" SET NOT NULL;
ALTER TABLE "expenseCategories" ALTER COLUMN "tenantId" SET NOT NULL;
ALTER TABLE "incomes" ALTER COLUMN "tenantId" SET NOT NULL;
ALTER TABLE "expenses" ALTER COLUMN "tenantId" SET NOT NULL;
ALTER TABLE "notes" ALTER COLUMN "tenantId" SET NOT NULL;
ALTER TABLE "remainders" ALTER COLUMN "tenantId" SET NOT NULL;
ALTER TABLE "attachments" ALTER COLUMN "tenantId" SET NOT NULL;

-- AddForeignKey
ALTER TABLE "users" ADD CONSTRAINT "users_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "incomeCategories" ADD CONSTRAINT "incomeCategories_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "expenseCategories" ADD CONSTRAINT "expenseCategories_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "incomes" ADD CONSTRAINT "incomes_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "expenses" ADD CONSTRAINT "expenses_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "notes" ADD CONSTRAINT "notes_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "remainders" ADD CONSTRAINT "remainders_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "auditlogs" ADD CONSTRAINT "auditlogs_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- DropIndex: replaced by the tenant-scoped composite index below
DROP INDEX "attachments_entityType_entityId_idx";

-- CreateIndex
CREATE UNIQUE INDEX "users_userEmail_key" ON "users"("userEmail");
CREATE INDEX "users_tenantId_idx" ON "users"("tenantId");

CREATE UNIQUE INDEX "incomeCategories_tenantId_categoryName_key" ON "incomeCategories"("tenantId", "categoryName");
CREATE INDEX "incomeCategories_tenantId_deletedAt_idx" ON "incomeCategories"("tenantId", "deletedAt");

CREATE UNIQUE INDEX "expenseCategories_tenantId_categoryName_key" ON "expenseCategories"("tenantId", "categoryName");
CREATE INDEX "expenseCategories_tenantId_deletedAt_idx" ON "expenseCategories"("tenantId", "deletedAt");

CREATE INDEX "incomes_tenantId_deletedAt_idx" ON "incomes"("tenantId", "deletedAt");
CREATE INDEX "incomes_tenantId_transactionDate_idx" ON "incomes"("tenantId", "transactionDate");

CREATE INDEX "expenses_tenantId_deletedAt_idx" ON "expenses"("tenantId", "deletedAt");
CREATE INDEX "expenses_tenantId_transactionDate_idx" ON "expenses"("tenantId", "transactionDate");

CREATE INDEX "notes_tenantId_deletedAt_idx" ON "notes"("tenantId", "deletedAt");
CREATE INDEX "remainders_tenantId_deletedAt_idx" ON "remainders"("tenantId", "deletedAt");

CREATE INDEX "auditlogs_tenantId_createdAt_idx" ON "auditlogs"("tenantId", "createdAt");

CREATE INDEX "attachments_tenantId_entityType_entityId_idx" ON "attachments"("tenantId", "entityType", "entityId");
CREATE INDEX "attachments_tenantId_deleted_at_idx" ON "attachments"("tenantId", "deleted_at");
